{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Inogatran, a structurally close peptidomimetic thrombin inhibitor with a basic guanidine, cyclohexylalanine, glycine, and lactam core, had oral bioavailability <5% in healthy volunteers, directly supporting low F for the query's free basic amidine/peptide-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Melagatran, another close analogue with an amidine and carboxylate peptidomimetic structure, showed human oral bioavailability of only 3–7%, supporting a low F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "DX-9065a, a benzamidine-containing factor Xa inhibitor, had human oral bioavailability of 2–3%, attributed to its strongly basic amidino groups; this supports low F for the query's benzamidine moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "AZD0837, a methoxy-amidoxime prodrug with a masked amidine, achieved 22–55% oral bioavailability in humans; this is contradictory to a low prediction but has limited transferability because the query contains a free amidine rather than the prodrug-masked form.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a free-amidine peptidomimetic thrombin inhibitor; close analogues with free basic amidine/guanidine groups (inogatran, melagatran, DX-9065a) show F <10%, while the only high-F analogue is a prodrug with a masked amidoxime, so the query is predicted low.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "The closest high-F analogue AZD0837 is a prodrug with a masked amidine, limiting transferability.",
    "No data on solubility, permeability, or efflux for the exact query under fasted conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

